class Solution:
    def minimumStrength(self, monsters: list[int], boosts: list[list[int]]) -> int:
        n = len(monsters)
        bonus = [0] * (n + 1)
        for l, r, v in boosts:
            bonus[l] += v
            bonus[r + 1] -= v
        for i in range(n):
            bonus[i + 1] += bonus[i]
        def ok(s):
            cur = s
            for i in range(n):
                if cur + bonus[i] < monsters[i]:
                    return False
                cur = max(0, cur - monsters[i])
            return True
        lo, hi = 0, sum(monsters)
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

