class Solution {
public:
    long long minimumStrength(vector<int>& monsters, vector<vector<int>>& boosts) {
        int n = monsters.size();
        vector<long long> bonus(n + 1, 0);
        for (auto& b : boosts) { bonus[b[0]] += b[2]; bonus[b[1] + 1] -= b[2]; }
        for (int i = 0; i < n; i++) bonus[i + 1] += bonus[i];
        long long lo = 0, hi = accumulate(monsters.begin(), monsters.end(), 0LL);
        auto ok = [&](long long s) {
            long long cur = s;
            for (int i = 0; i < n; i++) {
                if (cur + bonus[i] < monsters[i]) return false;
                cur = max(0LL, cur - monsters[i]);
            }
            return true;
        };
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (ok(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

