class Solution {
    public long minimumStrength(int[] monsters, int[][] boosts) {
        int n = monsters.length;
        long[] bonus = new long[n + 1];
        for (int[] b : boosts) { bonus[b[0]] += b[2]; bonus[b[1] + 1] -= b[2]; }
        for (int i = 0; i < n; i++) bonus[i + 1] += bonus[i];
        long lo = 0, hi = 0;
        for (int m : monsters) hi += m;
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            if (ok(mid, monsters, bonus)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
    private boolean ok(long s, int[] monsters, long[] bonus) {
        long cur = s;
        for (int i = 0; i < monsters.length; i++) {
            if (cur + bonus[i] < monsters[i]) return false;
            cur = Math.max(0, cur - monsters[i]);
        }
        return true;
    }
}

