var minimumStrength = function(monsters, boosts) {
    const n = monsters.length;
    const bonus = new Array(n + 1).fill(0);
    for (const [l, r, v] of boosts) { bonus[l] += v; bonus[r + 1] -= v; }
    for (let i = 0; i < n; i++) bonus[i + 1] += bonus[i];
    const ok = (s) => {
        let cur = s;
        for (let i = 0; i < n; i++) {
            if (cur + bonus[i] < monsters[i]) return false;
            cur = Math.max(0, cur - monsters[i]);
        }
        return true;
    };
    let lo = 0, hi = monsters.reduce((a, b) => a + b, 0);
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (ok(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
};

